from __future__ import annotations
import warnings

__doc__ = """
Hierarchical key-to-offset mapping primitives used throughout the project.

The keymap layer models symbolic layouts of contiguous memory. A
:class:`KeyMap` links symbolic keys to child domains, computes flat offsets for
the resulting tree, and resolves the inverse mapping from offsets back to keys
and domains. This allows higher layers to express algebra and generated code in
terms of symbolic subspaces instead of hard-coded indices.

Important concepts in this module are:

- :class:`Key`, which chains key segments to address nested domains
- tagged key segments, which remember the keymap they originated from and make
  accidental cross-map lookup mistakes easier to detect
- :class:`Domain`, the common parent for any contiguous managed region
- :class:`KeyMap`, the recursive symbolic container
- :class:`Region`, a dense integer-indexed specialization of :class:`KeyMap`
- :class:`Entry`, the size-one leaf domain used as the terminal storage unit

In practice this module is the bridge between symbolic descriptions of tensor
or operator layouts and the flat buffers that the ADAA, wrapper, and codegen
layers eventually operate on. Sphinx can render the API directly from the
module and routine docstrings below.
"""


import pickle

from typing import (
    Any,
    Callable,
    Generator,
    Iterable,
    Iterator,
    List,
    Tuple,
    Type,
    Self,
)
from collections.abc import Hashable


