class Key:
    """
    Keys can be composed from other keys to access nested keymaps. Internally,
    they store the _KeySegment objects they are made from. The main complexity
    of this class is due to the task of managing proper conversions and handling
    tagged keys.
    Tagged keys include a reference to the KeyMap that they apply to. In a safe
    design, these references are checked, figuratively we check wether the key
    fits into the lock it is designed for.
    """

    def __init__(self, *keys: Any):
        """
        Build a chained key from labels, key segments, or existing keys.

        :param keys: Key-like components to concatenate into one key.
            Components may be raw hashable labels, :class:`_KeySegment`
            instances, or existing :class:`Key` objects.
        """
        self._key_segments = []
        # decompose into _KeySegments
        for tkey in keys:
            if tkey is None:
                continue
            if isinstance(tkey, _KeySegment):
                self._key_segments += [tkey]  # no-copy
                # tkey.parnet._tagged_keyseg(tkey.label)  # copy
            elif isinstance(tkey, Key):
                self._key_segments += [
                    parent._to_tagged_keyseg(label)
                    if parent
                    else _KeySegment(label)
                    for parent, label in tkey._unchain(tagged=True)
                ]
            else:
                self._key_segments += [_KeySegment(tkey)]
        # and check
        if __debug__:
            for keyseg in self._key_segments:
                assert isinstance(keyseg, _KeySegment)

    @property
    def labels(self) -> Tuple[Any]:
        """
        Return the plain labels that make up the key.

        :returns: Tuple of label objects in chain order.
        """
        return tuple(kseg.label for kseg in self._key_segments)

    @property
    def parents(self) -> Tuple[Domain | None, ...]:
        """
        Return the tagged parent domains of all key segments.

        :returns: Tuple containing the parent domain of each key segment, or
            ``None`` for untagged segments.
        """
        return tuple(kseg.parent for kseg in self._key_segments)

    def onlylabel(self) -> Any:
        """
        Return the sole label stored in a single-segment key.

        :returns: The label of the only segment.
        :raises ValueError: If the key contains more than one segment.
        """
        if len(self._key_segments) != 1:
            raise ValueError("Key must have exactly one label")
        return self._key_segments[0].label

    def _as_list(self, tagged: bool = True) -> List[Tuple[Domain | None, Any]]:
        """
        Convert the key into a list representation.

        :param tagged: If ``True``, include parent tags in the output tuples.
        :returns: List of ``(parent, label)`` pairs.
        """
        return [
            (parent, kseg.label)
            for parent, kseg in self._unchain(tagged=tagged)
        ]

    def _unchain(
        self, tagged: bool = True
    ) -> Iterator[tuple[Domain | None, _KeySegment]]:
        """
        Unpack all the key objects chained up, together with their tags.

        :param tagged: whether to include parent tags in the generator.
        :returns: A generator of tuples, each containing a parent and a label.
                  If not tagged, the parent is None.
        """
        for kseg in self._key_segments:
            if tagged:
                yield (kseg.parent, kseg)
            else:
                yield (None, kseg)

    def __hash__(self) -> int:
        """As _KeySegments are hashable, so are tuples made from them."""
        return hash((self.labels, self.parents))

    def __gt__(self, other: Any) -> bool:
        if not isinstance(other, Key):
            raise ValueError("Can only compare Key objects")
        if len(self._key_segments) != len(other._key_segments):
            return False
        for (_, k_left), (_, k_right) in zip(
            self._unchain(), other._unchain()
        ):
            # check keys for compatability
            if k_left <= k_right:
                return False
        # if we got here, everything is fine I guess...
        return True

    def __eq__(self, other: Any) -> bool:
        """
        Check whether two keys match. Include parent check. If any of the
        two parents is None, assume them to be universal.
        """
        if not isinstance(other, Key):
            raise ValueError("Can only compare Key objects")
        if len(self._key_segments) != len(other._key_segments):
            return False
        for (p_left, k_left), (p_right, k_right) in zip(
            self._unchain(), other._unchain()
        ):
            # check keys for compatability
            if k_left != k_right:
                return False
            # check parents, but skip checks when universal tags are involved
            if p_left is None or p_right is None:
                continue
            if p_left != p_right:
                return False
        # if we got here, everything is fine I guess...
        return True

    def __repr__(self) -> str:
        return f"[{'|'.join(map(lambda x: str(x.label), self._key_segments))}]"

    def __str__(self) -> str:
        return f"<Key{self.__repr__()}>"

    def __or__(self, other: Any) -> Key:
        """
        Concatenate another key-like object to the right-hand side.

        :param other: Key-like object to append.
        :returns: New chained key.
        """
        if isinstance(other, (Key, _KeySegment)):
            return Key(self, other)
        return Key(self, _KeySegment(other))

    def __ror__(self, other: Any) -> Key:
        """
        Concatenate another key-like object to the left-hand side.

        :param other: Key-like object to prepend.
        :returns: New chained key.
        """
        if isinstance(other, (Key, _KeySegment)):
            return Key(other, self)
        return Key(_KeySegment(other), self)

    def __len__(self) -> int:
        return len(self._key_segments)


