class Domain:
    """
    We grow a tree-like data structure. Any named set of contiguous entries in
    this structure is referred to as a domain.

    This class serves as a generic parent class for any other data structure
    occuring in such a tree.

    The class handles the base functionality about name and update procedure
    as well as str and repr display.

    info: see this as an abstract class. Not supposed to be used directly.
    """

    _IDENTIFIER = "Domain"
    _IDENTIFIER_SHORT = "D"
    _enum = 0

    @autoname
    def __init__(self, *, name: str):
        """
        Initialize a named domain.

        :param name: Human-readable name used for display and auto-derived
            child keys.
        """
        self._name = name

        # start empty
        self._size = 0

        # contain domains, (nested) keymaps, regions or entries
        self._content = []  # format: [(kseg, domain), ...]

        # remember what you are attached to
        self._parents = []

        # start with False, better safe than sorry
        self._is_ud_flag = False

        # domain can be locked for change
        self._is_locked = False

    @property
    def is_locked(self) -> bool:
        """check if the domain is locked"""
        return self._is_locked

    @property
    def name(self) -> str:
        """
        Access protected variable name.

        :returns: the name."""
        return self._name

    @name.setter
    def name(self, name: str) -> None:
        """
        Rename the domain if it is not locked.

        :param name: New domain name.
        """
        if self.is_locked:
            raise RuntimeError("Domain is locked!")
        # warnings.warn(
        #     "Bad programmer, bad! But seriously, be careful with renaming."
        # )
        self._name = name

    @property
    def size(self) -> int:
        """
        Access read-only variable size.

        :returns: the size.
        """
        self._update_internals()
        return self._size

    def __str__(self):
        self._update_internals()
        return f"<{self._IDENTIFIER} '{self.name}'>"

    def __repr__(self):
        self._update_internals()
        return f"<{self._IDENTIFIER_SHORT}[{self.name}]>"

    def __len__(self) -> int:
        """Return the current size of the domain."""
        self._update_internals()
        return self._size

    def _update_internals(self, force: bool = False) -> bool:
        """
        Ensure the domain's cached indexing structures are up to date.

        :param force: If ``True``, run the update even when the domain is
            already marked up to date.
        :returns: ``True`` if the update completed successfully.
        :raises RuntimeError: If the subclass update routine reports failure.
        """
        if self.is_ud and not force:
            return True
        self._is_ud_flag = self._update(force=force)
        if not self._is_ud_flag:
            raise RuntimeError("update did not succeed")
        return True

    def _update(self, force: bool = False) -> bool:
        """
        Execute the subclass-specific update routine.

        :param force: If ``True``, force a full rebuild of cached structures.
        :returns: ``True`` on success.
        """
        raise NotImplementedError("Subclasses must implement this method")

    def update(self, force: bool = False) -> Self:
        """
        Public wrapper around the internal update routine.

        :param force: If ``True``, force a full rebuild of cached structures.
        :returns: ``self`` for chaining.
        """
        self._update_internals(force=force)
        return self

    @property
    def is_ud(self) -> bool:
        """Read-only access to update flag."""
        return self._is_ud_flag

    def flag_ud(self) -> Self:
        """
        Mark this Domain for update.

        :returns: ``self`` for chaining.
        """
        if self.is_locked:
            raise ValueError("Cannot flag locked domain for update")
        self._is_ud_flag = False
        for parent in self._parents:
            parent.flag_ud()
        return self

    @staticmethod
    def from_file(filename: str) -> Domain:
        """
        Load a serialized domain from disk and mark it stale.

        :param filename: Pickle file to read from.
        :returns: Loaded domain instance after re-running :meth:`update`.
        """
        dom = None
        with open(filename, "rb") as handle:
            dom = pickle.load(handle)
            dom.flag_ud()
            dom.__class__._enum += 1
            dom.update()
        assert dom is not None
        return dom

    def to_file(self, filename: str) -> Self:
        """
        Serialize the domain to disk.

        :param filename: Pickle file to write to.
        :returns: ``self`` for chaining.
        """
        self._update_internals()
        with open(filename, "wb") as handle:
            pickle.dump(self, handle)
        return self

    def add_parent(self, parent: Domain) -> Self:
        """
        Register another domain as a parent of this one.

        :param parent: Parent domain that references this instance.
        :returns: ``self`` for chaining.
        """
        if not isinstance(parent, Domain):
            raise ValueError("parent must be a Domain")
        if parent not in self._parents:
            self._parents.append(parent)
        return self

    def keys(
        self, recursive: bool = False, prefix: Key | None = None
    ) -> Iterator[Key]:
        """
        Yield keys that address this domain.

        :param recursive: If ``True``, yield keys recursively for nested child
            domains.
        :param prefix: Optional key prefix supplied by parent domains.
        :returns: Iterator of keys.
        """
        # we break the recursive call here.
        self._update_internals()
        if recursive:
            if prefix is None:
                prefix = Key()
            yield Key(prefix)
        return
        yield

    def items(
        self, recursive: bool = False, prefix: Key | None = None
    ) -> Iterator[tuple[Key, Domain]]:
        """
        Yield ``(key, domain)`` pairs for this domain.

        :param recursive: If ``True``, recurse into child domains.
        :param prefix: Optional key prefix supplied by parent domains.
        :returns: Iterator of ``(key, domain)`` tuples.
        """
        # we break the recursive call here.
        self._update_internals()
        if recursive:
            if prefix is None:
                prefix = Key()
            yield Key(prefix), self
        return
        yield

    def values(self, recursive: bool = False) -> Iterator[Domain]:
        """
        Yield child domains.

        :param recursive: If ``True``, recurse into child domains.
        :returns: Iterator of domains.
        """
        # we break the recursive call here.
        self._update_internals()
        if recursive:
            yield self
        return
        yield

    def lock(self) -> Self:
        """
        Lock this domain and all nested child domains against further mutation.

        :returns: ``self`` for chaining.
        """
        self.update()
        for _kseg, content in self._content:
            content.lock()
        self._is_locked = True
        return self

    def tree(
        self, level: int = 0, key: Key | None = None
    ) -> Iterator[tuple[int, Key | None, Domain]]:
        """
        Yield a structural tree view of this domain hierarchy.

        :param level: Current nesting level, used internally during recursion.
        :param key: Key that reaches the current domain from the root, if any.
        :returns: Iterator yielding ``(level, key, domain)`` tuples.
        """
        yield level, key, self
        for key, domain in self.items():
            yield from domain.tree(level=level + 1, key=key)


