class KeyMap(Domain):
    """Hierarchical mapping from symbolic keys to child domains and offsets."""

    _IDENTIFIER = "KeyMap"
    _IDENTIFIER_SHORT = "KM"
    _enum = 0

    @autoname
    def __init__(self, *, name: str | None = None):
        """
        Initialize an empty keymap.

        :param name: Optional keymap name. When omitted, a unique autogenerated
            name is assigned by :func:`autoname`.
        """
        super().__init__(name=name)

        # lookup tables
        self._off2dom = []  # translate from offset to dom and remaining offset
        self._off2key = []  # translate from offset to key
        self._key2off = {}  # translate the key to its offset
        self._key2dom = {}  # key objects are keys to doms

        # reset
        self._reset()

        self._kseg_factory = self._create_keyseg_factory(name)

    def _reset(self) -> None:
        """Reset cached lookup tables and size bookkeeping."""
        assert not self.is_locked
        self._is_ud_flag = False
        self._size = 0
        self._off2dom = []
        self._off2key = []
        self._key2off = {}
        self._key2dom = {}

    def key(self, keylike: Any, /) -> Key:
        """
        Create a tagged key belonging to this keymap.

        :param keylike: Hashable label, :class:`Key`, or :class:`_KeySegment`
            convertible to a single-segment key.
        :returns: Tagged key object.
        """
        label = keylike
        if isinstance(label, Key):
            label = label.onlylabel()
        elif isinstance(label, _KeySegment):
            label = label.label
        else:
            if not isinstance(label, Hashable):
                raise ValueError("keylike must be a Hashable object")
        return Key(self._kseg_factory(label))

    def _tagged_keyseg(self, label: Hashable) -> _KeySegment:
        """Return a tagged key segment produced by this keymap's factory."""
        return self._kseg_factory(label)

    def _create_keyseg_factory(self, name: str) -> Type:
        """
        Build the private key-segment factory bound to this keymap.

        :param name: Keymap name used for the generated class name.
        :returns: Subclass of :class:`_KeySegment` tagged to this keymap.
        """
        # inherit from _KeySegment and set self as the default parent
        factory = type(
            f"auto_KeyGen_{name}",
            (_KeySegment,),
            {
                "__doc__": f"key generator for keymap '{name}'.",
            },
            parent=self,
        )
        return factory

    def reorder(self, function: Callable[[Key, Domain], Any]) -> Self:
        """
        Reorder child domains by a user-supplied sort key.

        :param function: Callable receiving ``(key, domain)`` and returning a
            sortable value, or ``None`` to drop the entry from the reordered
            list.
        :returns: ``self`` for chaining.
        """
        if self.is_locked:
            raise ValueError("Cannot reorder locked KeyMap")
        aux = sorted(
            [
                (sort_id, key, keymap)
                for key, keymap in self._content
                if (sort_id := function(Key(key), keymap)) is not None
            ]
        )
        self._content = [(key, keymap) for _, key, keymap in aux]
        return self

    def entry(self, keylike: Any, /) -> Self:
        """
        Create and link a new :class:`Entry` under the given key.

        :param keylike: Hashable label or single-segment key.
        :returns: ``self`` for chaining.
        """
        if self.is_locked:
            raise ValueError("Cannot add entry to a locked domain")
        key = self.key(keylike)
        self.link(key, Entry(name=key.onlylabel()))
        return self

    def extend(self, domain: Domain, autorename: bool = True) -> Self:
        """
        Insert a domain under a key derived from its current name.

        :param domain: Domain to attach.
        :param autorename: If ``True``, append numeric suffixes until a free
            derived key is found.
        :returns: ``self`` for chaining.
        """
        if self.is_locked:
            raise ValueError("Cannot extend locked domain")
        if not isinstance(domain, Domain):
            raise ValueError("Not a Domain")
        name = domain.name
        kseg = self._tagged_keyseg(name)

        # find a working kseg or raise exception
        if kseg in self:
            if autorename:
                num = 1
                while kseg in self:
                    num += 1
                    name = f"{domain.name}.{num}"
                    kseg = self._tagged_keyseg(name)
            else:
                raise KeyError(f"Key '{kseg.label}' already exists")
        self._link(kseg, domain)
        return self

    def link(
        self, keylike: Any, /, domain: Domain | None, no_override: bool = True
    ) -> Self:
        """
        Link a key to a domain explicitly.

        :param keylike: Hashable label, :class:`Key`, or :class:`_KeySegment`
            identifying the link location.
        :param domain: Domain to link. If ``None``, a new :class:`Entry` is
            created automatically.
        :param no_override: If ``True``, raise when the key already exists.
        :returns: ``self`` for chaining.
        """

        if self.is_locked:
            raise ValueError("Cannot add to a locked keymap")

        pointer = self
        if isinstance(keylike, Key):
            parent_key_list = list(keylike._unchain())
            for parent, key in parent_key_list[:-1]:
                if parent is not None:
                    assert pointer == parent
                pointer = pointer[key]
            parent, keylike = parent_key_list[-1]
            if parent is not None:
                assert pointer == parent

        # use a kseg from this map
        kseg = pointer._to_tagged_keyseg(keylike)

        if domain is None:
            # default thing to add is an entry
            domain = Entry(name=str(kseg.label))

        # check if key is duplicate
        if no_override:
            if kseg in self:
                raise KeyError(f"Key '{kseg}' already exists")
        pointer._link(kseg, domain)
        return self

    def _link(self, kseg: _KeySegment, domain: Domain) -> Self:
        """
        Attach a domain under a tagged key segment without duplicate checks.

        :param kseg: Tagged key segment owned by this keymap.
        :param domain: Domain to attach.
        :returns: ``self`` for chaining.
        """

        # acutal append
        self._append(kseg, domain)

        # register the current domain as a parent to the included domain
        domain.add_parent(self)
        self.flag_ud()
        return self

    def _append(self, kseg: _KeySegment, domain: Domain) -> None:
        """Append one raw ``(key segment, domain)`` pair to the content list."""
        assert isinstance(kseg, _KeySegment)
        assert isinstance(domain, Domain)
        self._content.append((kseg, domain))

    def _update(self, force: bool = False) -> bool:
        """
        Rebuild all key-to-offset and offset-to-domain lookup tables.

        :param force: Forwarded to child domains during update.
        :returns: ``True`` once the internal caches have been rebuilt.
        """
        self._reset()
        offset_pointer = 0

        # go through domains in content
        for tkey, domain in self._content:
            ret = domain.update(force=force)
            if not ret:
                raise RuntimeError("domain update failed")
            if domain.size <= 0:
                warnings.warn(f"domain {domain} is empty")
                continue

            # move into the selected domain
            self._key2dom[tkey] = domain
            self._key2off[tkey] = offset_pointer
            for offset in range(len(domain)):
                self._off2dom.append((domain, offset))
                self._off2key.append((tkey))
                offset_pointer += 1
        assert len(self._off2dom) == offset_pointer
        self._size = offset_pointer
        return True

    def __getitem__(self, key: Any) -> Domain:
        """Return the domain addressed by ``key``."""
        _, entry = self.goto(key)
        return entry

    def __contains__(self, keylike: Any) -> bool:
        """Check whether a key exists directly in this keymap."""
        kseg = self._to_tagged_keyseg(keylike)
        for tkey, _ in self._content:
            if tkey == kseg:
                return True
        return False

    def _to_tagged_keyseg(self, keylike: Any) -> _KeySegment:
        """
        Convert a key-like object into a key segment tagged to this keymap.

        :param keylike: Hashable label, :class:`Key`, or :class:`_KeySegment`.
        :returns: Tagged key segment owned by this keymap.
        """

        label = keylike  # assume hashable if no other conditional checks out

        # check if key
        if isinstance(keylike, Key):
            if len(keylike) != 1:
                raise ValueError("Key cannot be a chained key")
            label = keylike.onlylabel()

        # check if keysegment
        if isinstance(keylike, _KeySegment):
            label = keylike.label

        # use a kseg from this map
        return self._tagged_keyseg(label)

    def keys(self, recursive: bool = False, prefix: Key | None = None):
        """
        The generator equivalent to dict's keys function.

        :param recursive: whether to forward recursive call for each domain
        :param prefix: a Key to start from
        :returns: a generator of Key objects
        """
        # we COULD have prefix: Key = Key() in the args list, as the empty key
        # as default could be a monad, but it is cleaner like that.
        self._update_internals()
        if prefix is None:
            prefix = Key()
        for key, dom in self._key2dom.items():
            if recursive:
                yield from dom.keys(recursive=True, prefix=Key(prefix, key))
            else:
                yield Key(prefix, key)

    def items(self, recursive: bool = False, prefix: Key | None = None):
        """
        The generator equivalent to dict's items function

        :param recursive: whether to forward recursive call for each domain
        :param prefix: a Key to start from
        :returns: a generator of Key objects
        """
        self._update_internals()
        if prefix is None:
            prefix = Key()
        for key, dom in self._key2dom.items():
            if recursive:
                yield from dom.items(recursive=True, prefix=Key(prefix, key))
            else:
                yield Key(prefix, key), dom

    def values(self, recursive: bool = False):
        """
        The generator equivalent to dict's values function

        :param recursive: whether to forward recursive call for each domain
        :returns: a generator of Key objects
        """
        self._update_internals()
        for _, dom in self._key2dom.items():
            if recursive:
                yield from dom.values(recursive=True)
            else:
                yield dom

    def _key2offdom(self, *keys: Any) -> tuple[int, Domain]:
        """
        Resolve a chained key to its flat offset and terminal domain.

        :param keys: Key-like components forming one chained key.
        :returns: ``(offset, domain)`` pair.
        """
        self._update_internals()
        key = Key(*keys)
        current_obj = self
        current_pos = 0
        for kmap, kseg in key._unchain():
            if kmap is not None:
                if kmap != current_obj:
                    raise KeyError(
                        f"Tagged key {kseg.label} not from keymap {current_obj}"
                    )
            if kseg not in current_obj._key2off:
                raise KeyError(
                    f"Cannot find key {kseg} in domain '{current_obj}'"
                )
            current_pos += current_obj._key2off[kseg]
            current_obj = current_obj._key2dom[kseg]

        return current_pos, current_obj

    def _off2keydom(
        self, offset: int, *, _collect: Key | None = None
    ) -> tuple[Key, Domain]:
        """
        Resolve a flat offset back into a key/domain pair.

        :param offset: Flat offset within this keymap.
        :param _collect: Internal key accumulator used during recursion.
        :returns: ``(key, domain)`` pair.
        """
        self._update_internals()
        if _collect is None:
            _collect = Key()
        if isinstance(self, Entry) or not self._key2dom:
            assert isinstance(_collect, Key)
            return _collect, self  # RETURN
        this_key = self._off2key[offset]
        next_domain, remaining_offset = self._off2dom[offset]
        return next_domain._off2keydom(
            remaining_offset, _collect=Key(_collect, this_key)
        )

    # public routines
    # ===============

    def key2off(self, *keys: Any) -> int:
        """
        Resolve a key to its flat offset.

        :param keys: Key-like components forming one chained key.
        :returns: Offset of the addressed domain region.
        """
        off, _ = self._key2offdom(*keys)
        return off

    def key2dom(self, *keys: Any) -> Domain:
        """
        Resolve a key to its terminal domain.

        :param keys: Key-like components forming one chained key.
        :returns: Addressed domain.
        """
        _, domain = self._key2offdom(*keys)
        return domain

    def goto(self, *keys: Any) -> tuple[int, Domain]:
        """
        Resolve a key to both offset and domain.

        :param keys: Key-like components forming one chained key.
        :returns: ``(offset, domain)`` pair.
        """
        return self._key2offdom(*keys)

    def off2key(self, offs: int) -> Key:
        """
        Resolve an offset to the corresponding symbolic key.

        :param offs: Flat offset within this keymap.
        :returns: Key reaching the addressed leaf domain.
        """
        key, _ = self._off2keydom(offs, _collect=Key())
        return key

    def off2dom(self, offs: int) -> Domain:
        """
        Resolve an offset to the corresponding domain.

        :param offs: Flat offset within this keymap.
        :returns: Addressed domain.
        """
        _, domain = self._off2keydom(offs, _collect=Key())
        return domain

    def move(self, offs: int) -> tuple[Key, Domain]:
        """
        Resolve an offset to both symbolic key and terminal domain.

        :param offs: Flat offset within this keymap.
        :returns: ``(key, domain)`` pair.
        """
        return self._off2keydom(offs, _collect=Key())


