#
#  .oPYo.                   o
#  8   `8
# o8YooP'  .oPYo.  .oPYo.  o8  .oPYo.  odYo.
#  8   `b  8oooo8  8    8   8  8    8  8' `8
#  8    8  8.      8    8   8  8    8  8   8
#  8    8  `Yooo'  `YooP8   8  `YooP'  8   8
# :..:::.. :.....: :....8  :.. :.....: ..::..
# :::::::: ::::::: ::ooP'. ::: ::::::: ::::::
# :::::::: ::::::: ::...:: ::: ::::::: ::::::
###############################################################################


class Region(KeyMap):
    """
    Region is a special keymap which is trivially indexed by integer keys
    """

    _IDENTIFIER = "Region"
    _IDENTIFIER_SHORT = "R"
    _enum = 0

    def __init__(self, size: int, *, name: str | None = None):
        """
        Initialize a region with ``size`` entry slots.

        :param size: Number of entries to create immediately.
        :param name: Optional region name.
        """
        super().__init__(name=name)
        self._counter = 0
        for count in range(size):
            self.entry()
        self._update_internals()

    def link(self, keylike, /, domain, no_override=True):
        """
        Regions are internally managed, so this will raise an Exception.

        :raises: RuntimeError, as this operation is not allowed.
        """
        raise RuntimeError(
            "Placing in regions is not suppoerted. Use 'entry' instead."
        )

    def extend(self, domain: Domain, autorename: bool = False):
        """
        Append one :class:`Entry` to the end of the region.

        :param domain: Entry to append.
        :param autorename: Accepted for API compatibility. It has no semantic
            effect for regions.
        :raises ValueError: If ``domain`` is not an :class:`Entry`.
        """
        if self.is_locked:
            raise ValueError("Cannot add to a locked domain")
        if not isinstance(domain, Entry):
            raise ValueError("Can only extend with Entry objects")
        if autorename:
            warnings.warn("autorename has no effect in Region.extend")
        kseg = self._tagged_keyseg(self._counter)
        self._link(kseg, domain)
        self._counter += 1

    def entry(self, keylike: Any | None = None, /):
        """
        Create and append one new entry at the next integer index.

        :param keylike: Optional label used as the entry name.
        """
        if self.is_locked:
            raise ValueError("Cannot add new entry to a locked domain")
        if keylike is None:
            entry = Entry(name=f"{self.name}@{self._counter}")
        else:
            entry = Entry(name=self._to_tagged_keyseg(keylike).label)
        self.extend(domain=entry)

    def reorder(self, function):
        """Reject reordering because region indices are defined by position."""
        raise RuntimeError("Cannot reorder regions.")


