#
# .oPYo.           o
# 8.               8
# `boo    odYo.   o8P  oPYo.  o    o
# .P      8' `8    8   8  `'  8    8
# 8       8   8    8   8      8    8
# `YooP'  8   8    8   8      `YooP8
# :.....: ..::.. ::..: ..:::: :....8
# ::::::: :::::: ::::: :::::: ::ooP'.
# ::::::: :::::: ::::: :::::: ::...::
###############################################################################


class Entry(Region):
    """
    An Entry is formally a Region of size 1 with no keys allowed inside.
    """

    _IDENTIFIER = "Entry"
    _IDENTIFIER_SHORT = "E"
    _enum = 0

    def __init__(self, *, name: str | None = None):
        """
        Initialize a leaf entry of size one.

        :param name: Optional entry name.
        """
        super().__init__(0, name=name)
        # init with 0, no entries are appended inside
        self._content = []
        self._size = 1
        self._is_ud_flag = True
        self._is_locked = True

    # -----------------------------------------------------------------------
    # important: keys, items and values break the recursive call here!
    # The breakers are basically designed itentically to the ones in Domain,
    # but it's clearer if they are redefined here properly.

    def keys(self, recursive=False, prefix: Key | None = None):
        """
        The generator equivalent to dict's keys function.

        :param recursive: whether to forward recursive call for each domain
        :param prefix: a Key to start from
        :returns: a generator of Key objects
        """
        # we break the recursive call here.
        self._update_internals()
        if recursive:
            if prefix is None:
                prefix = Key()
            yield Key(prefix)
        return
        yield

    def items(self, recursive=False, prefix: Key | None = None):
        """
        The generator equivalent to dict's items function

        :param recursive: whether to forward recursive call for each domain
        :param prefix: a Key to start from
        :returns: a generator of Key objects
        """
        # we break the recursive call here.
        self._update_internals()
        if recursive:
            if prefix is None:
                prefix = Key()
            yield Key(prefix), self
        return
        yield

    def values(self, recursive=False):
        """
        The generator equivalent to dict's values function

        :param recursive: whether to forward recursive call for each domain
        :returns: a generator of Key objects
        """
        # we break the recursive call here.
        self._update_internals()
        if recursive:
            yield self
        return
        yield

    # -----------------------------------------------------------------------

    def _update(self, force: bool = False) -> bool:
        """
        Reassert the fixed-size entry invariants.

        :param force: Accepted for API compatibility.
        :returns: Always ``True``.
        """
        # just to be sure, let us reassure the initialization here
        self._size = 1
        return True

    def __len__(self):
        return 1

    def lock(self) -> Self:
        """Lock the entry and return ``self`` for API consistency."""
        self._is_locked = True
        return self

    def _create_keyseg_factory(self, name: str):
        """Disable nested key generation below an entry."""
        # No keys allowed
        return _ForbiddenKey

    def reorder(self, function):
        """Ignore reordering requests on an entry."""
        if self.is_locked:
            raise ValueError("Cannot add to a locked domain")
        return self

    def link(self, keylike, /, domain, no_override=True):
        """Reject extension of an entry with another domain."""
        raise ValueError("Entries cannot be extended.")

    def extend(self, domain, autorename=True):
        """Reject extension of an entry with another domain."""
        raise ValueError("Entries cannot be extended.")

    def entry(self, keylike=None, /):
        """Reject creation of nested entries below an entry."""
        raise ValueError("Entries cannot be extended.")
